/**
 * Unit tests for DefaultTypeResolverBuilder#useForType
 */
public class DefaultTypeResolverBuilder_useForType_TriageGen1Test {

    private TypeFactory typeFactory;

    // Accessing the inner class via a subclass or reflection if necessary, 
    // but since DefaultTypeResolverBuilder is public, we use it directly.
    // The enum DefaultTyping is used in the constructor.

    public enum DefaultTyping {
        NON_FINAL,
        OBJECT_AND_NON_CONCRETE,
        NON_CONCRETE_AND_ARRAYS,
        JAVA_LANG_OBJECT,
        EVERYTHING
    }

    @Before
    public void setup() {
        typeFactory = TypeFactory.defaultInstance();
    }

    private ObjectMapper.DefaultTypeResolverBuilder createBuilder(DefaultTyping typing) {
        return new ObjectMapper.DefaultTypeResolverBuilder(typing);
    }

    @Test
    public void testUseForType_JavaLangObject_Default() {
        // Tests the default case (e.g., JAVA_LANG_OBJECT)
        ObjectMapper.DefaultTypeResolverBuilder builder = createBuilder(DefaultTyping.JAVA_LANG_OBJECT);
        JavaType javaLangObject = typeFactory.constructType(Object.class);

        assertTrue(builder.useForType(javaLangObject));

        JavaType stringType = typeFactory.constructType(String.class);
        assertFalse(builder.useForType(stringType));
    }

    @Test
    public void testUseForType_NonConcreteAndArrays_WithArray() {
        // Tests NON_CONCRETE_AND_ARRAYS logic: strip array, strip reference, check non-concrete/Object
        ObjectMapper.DefaultTypeResolverBuilder builder = createBuilder(DefaultTyping.NON_CONCRETE_AND_ARRAYS);

        // Case: Array of Object (Object is java.lang.Object)
        JavaType objectArray = typeFactory.constructType(Object[].class);
        assertTrue(builder.useForType(objectArray));

        // Case: Array of String (String is concrete)
        JavaType stringArray = typeFactory.constructType(String[].class);
        assertFalse(builder.useForType(stringArray));
    }

    @Test
    public void testUseForType_ObjectAndNonConcrete_ReferenceType() {
        // Tests OBJECT_AND_NON_CONCRETE logic: strip reference, check non-concrete/Object
        ObjectMapper.DefaultTypeResolverBuilder builder = createBuilder(DefaultTyping.OBJECT_AND_NON_CONCRETE);

        // Mocking a reference type like Optional<String>
        JavaType mockRefType = Mockito.mock(JavaType.class);
        JavaType mockReferencedType = Mockito.mock(JavaType.class);

        when(mockRefType.isReferenceType()).thenReturn(true).thenReturn(false);
        when(mockRefType.getReferencedType()).thenReturn(mockReferencedType);
        when(mockReferencedType.isJavaLangObject()).thenReturn(true);

        assertTrue(builder.useForType(mockRefType));

        // Test non-concrete but not TreeNode
        when(mockRefType.isReferenceType()).thenReturn(false);
        when(mockRefType.isJavaLangObject()).thenReturn(false);
        when(mockRefType.isConcrete()).thenReturn(false);
        when(mockRefType.getRawClass()).thenReturn(java.util.List.class);

        assertTrue(builder.useForType(mockRefType));

        // Test non-concrete but is TreeNode
        when(mockRefType.getRawClass()).thenReturn(TreeNode.class);
        assertFalse(builder.useForType(mockRefType));
    }

    @Test
    public void testUseForType_NonFinal_Logic() {
        // Tests NON_FINAL logic: strip array, strip reference, check !isFinal && !TreeNode
        ObjectMapper.DefaultTypeResolverBuilder builder = createBuilder(DefaultTyping.NON_FINAL);

        // Case: Interface (not final, not TreeNode)
        JavaType interfaceType = typeFactory.constructType(java.util.List.class);
        assertTrue(builder.useForType(interfaceType));

        // Case: Final class (String)
        JavaType finalType = typeFactory.constructType(String.class);
        assertFalse(builder.useForType(finalType));

        // Case: TreeNode (even if not final)
        JavaType treeNodeType = Mockito.mock(JavaType.class);
        when(treeNodeType.isArrayType()).thenReturn(false);
        when(treeNodeType.isReferenceType()).thenReturn(false);
        when(treeNodeType.isFinal()).thenReturn(false);
        when(treeNodeType.getRawClass()).thenReturn(TreeNode.class);
        assertFalse(builder.useForType(treeNodeType));
    }

    @Test
    public void testUseForType_NonFinal_WithArrayAndReference() {
        ObjectMapper.DefaultTypeResolverBuilder builder = createBuilder(DefaultTyping.NON_FINAL);

        // Mock structure: Array -> ReferenceType -> NonFinalClass
        JavaType arrayType = Mockito.mock(JavaType.class);
        JavaType refType = Mockito.mock(JavaType.class);
        JavaType targetType = Mockito.mock(JavaType.class);

        when(arrayType.isArrayType()).thenReturn(true);
        when(arrayType.getContentType()).thenReturn(refType);

        when(refType.isArrayType()).thenReturn(false);
        when(refType.isReferenceType()).thenReturn(true);
        when(refType.getReferencedType()).thenReturn(targetType);

        when(targetType.isArrayType()).thenReturn(false);
        when(targetType.isReferenceType()).thenReturn(false);
        when(targetType.isFinal()).thenReturn(false);
        when(targetType.getRawClass()).thenReturn(java.util.Map.class);

        assertTrue(builder.useForType(arrayType));
    }

    @Test
    public void testBuildMethods_Dummy() {
        // Ensure these methods don't crash if called (they likely throw NPE or are not intended for this test)
        ObjectMapper.DefaultTypeResolverBuilder builder = createBuilder(DefaultTyping.EVERYTHING);
        assertFalse(builder.buildTypeDeserializer(null, null, null) instanceof com.fasterxml.jackson.databind.deser.std.StdDeserializer);
    }
}
